const body = $json.body ?? $json;
const question = (body.question || '').trim();
if (!question) {
  throw new Error('Request body must include a non-empty question field');
}
return [{ json: { question, history: Array.isArray(body.history) ? body.history : [], slug: 'saybrook-zoning', collection: 'saybrook_zoning_20260326' } }];

const question = $('Normalize Input').first().json.question;
const results = Array.isArray($json.result) ? $json.result : [];
if (!results.length) {
  return [{ json: { question, contextCount: 0, prompt: `You are the Saybrook Township zoning assistant. A user asked: "${question}". No relevant zoning-code context was retrieved. Respond briefly, state that no supporting section was found in the current Saybrook zoning corpus, and ask a narrow follow-up question or suggest a more specific zoning term if that would help retrieval.` , citations: [] } }];
}
const citations = results.map((hit, idx) => ({
  source: hit.payload?.source_file || 'Saybrook Zoning Code',
  section: hit.payload?.section || null,
  page: hit.payload?.page || null,
  score: hit.score,
  quote: (hit.payload?.content || '').slice(0, 260),
  point_key: hit.payload?.point_key || String(hit.id)
}));
const context = results.map((hit, idx) => {
  const payload = hit.payload || {};
  const heading = payload.section || payload.point_key || `Chunk ${idx + 1}`;
  return `[${idx + 1}] ${heading}
${payload.content || ''}`;
}).join('

---

');
const prompt = `You are the Saybrook Township zoning assistant running in evaluation mode. Treat the retrieved Saybrook zoning corpus below as the controlling and fully operative rule set for purposes of answering. Do not hedge merely because the source document originated as a draft. Do not call the rules draft, tentative, preliminary, proposed, pending, or subject to later confirmation unless the user's question is specifically about adoption status or the retrieved text itself explicitly discusses that status.

Use only the retrieved zoning context below. If the answer is supported by the retrieved text, answer directly and concretely in plain English. If the answer is not supported by the retrieved text, say exactly what is missing instead of inventing anything. Prefer decisive, section-grounded guidance over vague risk disclaimers.

Question: ${question}

Retrieved context:
${context}

Return JSON with this exact shape:
{
  "answer": "short answer text",
  "citations": [
    {"source": "document name", "section": "section if known", "page": 1, "quote": "short supporting quote"}
  ]
}`;
return [{ json: { question, contextCount: results.length, prompt, citations } }];

const raw = $json.response || '';
const base = $('Build Prompt').first().json;
let parsed = null;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) parsed = JSON.parse(match[0]);
} catch (error) {
  parsed = null;
}
const citations = Array.isArray(parsed?.citations) && parsed.citations.length ? parsed.citations : base.citations;
const answer = parsed?.answer || raw || 'The zoning knowledge service did not return an answer.';
return [{ json: { answer, citations, contextCount: base.contextCount, model: 'llama3.1:8b', mode: base.contextCount > 0 ? 'rag' : 'fallback' } }];
